// Probiert moegliche Angebotsendpunkte durch und meldet je Versuch
// nur Statuscode, Anzahl der Eintraege und Feldnamen. Keine Klardaten.

const auth = $('S15 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const probe = $('S15 Angebotskennung holen').first().json;
const angebot = probe.eine_kennung;

if (!angebot) {
  throw new Error('Keine Angebotskennung in der Datenbank gefunden.');
}

const basis = 'https://app1.edoobox.com/v2';

const versuche = [
  { zweck: 'Angebotsliste', pfad: '/offer/list' },
  { zweck: 'Angebotsliste kurz', pfad: '/offer' },
  { zweck: 'Angebot einzeln', pfad: `/offer/${encodeURIComponent(angebot)}/data` },
  { zweck: 'Angebot einzeln kurz', pfad: `/offer/${encodeURIComponent(angebot)}` },
  { zweck: 'Angebotsgruppen', pfad: '/offerlist/list' },
  { zweck: 'Kategorien', pfad: '/category/list' },
  { zweck: 'Termine', pfad: '/date/list' },
  { zweck: 'Lektionen', pfad: '/lesson/list' },
  { zweck: 'Kurse', pfad: '/course/list' },
  { zweck: 'Preiskategorien', pfad: '/pricecategory/list' },
];

function feldnamen(o) {
  if (!o || typeof o !== 'object') return String(typeof o);
  return Object.keys(o).slice(0, 40).join(', ');
}

async function versuch(v) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: 'GET',
      url: basis + v.pfad,
      headers,
      qs: { 'limit[start]': 0, 'limit[reply]': 3 },
      json: true,
      returnFullResponse: true,
      timeout: 45000,
      ignoreHttpStatusErrors: true,
    });

    const koerper = antwort.body ?? {};
    const inhalt = koerper.data;

    let anzahl = 0;
    let erstes = null;

    if (Array.isArray(inhalt)) {
      anzahl = inhalt.length;
      erstes = inhalt[0];
    } else if (inhalt && typeof inhalt === 'object') {
      const werte = Object.values(inhalt);
      anzahl = werte.length;
      erstes = werte[0];
    }

    return {
      schritt: 'S15',
      zweck: v.zweck,
      pfad: v.pfad.replace(/offer_[0-9a-f]+_[0-9]+/i, '{angebot}'),
      status: antwort.statusCode,
      gemeldet_total: koerper.limit?.total ?? null,
      eintraege: anzahl,
      huellenfelder: feldnamen(koerper),
      datenfelder: erstes && typeof erstes === 'object' ? feldnamen(erstes) : '',
    };
  } catch (e) {
    return {
      schritt: 'S15',
      zweck: v.zweck,
      pfad: v.pfad.replace(/offer_[0-9a-f]+_[0-9]+/i, '{angebot}'),
      status: e.statusCode ?? 'Fehler',
      gemeldet_total: null,
      eintraege: 0,
      huellenfelder: String(e.message ?? e).slice(0, 120),
      datenfelder: '',
    };
  }
}

const laufen = versuch.bind(this);
const zeilen = [];

for (const v of versuche) {
  zeilen.push(await laufen(v));
}

zeilen.push({
  schritt: 'S15',
  zweck: 'ZUSAMMENFASSUNG',
  pfad: '',
  status: '',
  gemeldet_total: probe.verschiedene_angebote,
  eintraege: probe.buchungen,
  huellenfelder: 'verschiedene Angebote laut Datenbank',
  datenfelder: '',
});

return zeilen.map((z) => ({ json: z }));
